/* FOAD — Les bilans, SNV, cadre juridique, crise, brancardage, sécurité */

VSAV.chap({
  id: 'bilans', part: 'foad', seq: 'FOAD 1.1 — Les bilans', title: 'Les bilans : vue d’ensemble et bilan circonstanciel', short: 'Bilan circonstanciel',
  motif: 'eye', sources: ['PR - Bilan circonstanciel (MAJ 05/2024)', 'PR - Bilan secondaire (schéma chronologique)', 'AC - Protection et sécurité'],
  summary: 'Comment s’enchaînent les bilans et ce que vérifie l’équipe en arrivant sur les lieux.',
  why: '<b>Pourquoi un bilan circonstanciel ?</b> Un secouriste blessé ne sauve personne et devient une victime de plus. Avant même de toucher la victime, on regarde la scène : quels dangers menacent les intervenants, l’entourage et la victime ? Sont-ils maîtrisables ? Faut-il des moyens supplémentaires ? C’est aussi à ce moment que l’on récolte les indices qui orienteront tout le reste (mécanisme d’un traumatisme → suspicion d’atteinte du rachis, nombre de victimes…).',
  sections: [
    { id: 'chaine', t: 'L’enchaînement des bilans', ic: 'ecg', src: 'PR - Bilan secondaire, PR - Bilan primaire, PR - Bilan de surveillance',
      html: '<p>La prise en charge suit toujours la même chronologie : <b>départ en intervention → présentation sur intervention (bilan circonstanciel) → contact avec la victime (bilan primaire) → bilan secondaire → surveillance</b>. Les transmissions (demande de moyens supplémentaires, demande médicale, transmission du bilan à la coordination) s’intercalent dès que nécessaire.</p>',
      figs: [{ anim: 'bilans', cap: 'Animation : la chaîne des bilans', txt: '<p>Clique sur chaque étape ou lance le déroulé. Chaque bilan a un objectif différent : <b>sécuriser</b>, <b>repérer ce qui tue</b>, <b>chiffrer et examiner</b>, <b>suivre l’évolution</b>.</p>', src: 'PR - Bilan secondaire (schéma), PR - Bilan primaire' }] },
    { id: 'circonstanciel', t: 'Le bilan circonstanciel', ic: 'shield', src: 'PR - Bilan circonstanciel',
      html: '<p>La fiche le résume en deux questions :</p><ul class="check"><li><b>Prévention des dangers</b> : pour les intervenants, l’entourage, la (les) victime(s)…</li><li><b>Les dangers sont-ils maîtrisables ?</b> Sinon : demande de moyens de secours supplémentaires.</li></ul>' +
        '<p>L’apport de connaissances « Protection et sécurité » détaille la démarche :</p>',
      steps: ['Effectuer une approche prudente de la zone pour évaluer les dangers potentiels pour les intervenants et les témoins.', 'Repérer les personnes exposées et le nombre de victimes ; se renseigner éventuellement auprès des témoins.', 'Regarder autour de la victime, en restant à distance, pour évaluer les dangers persistants.', 'Délimiter clairement, largement et visiblement la zone d’intervention ou de danger et empêcher toute intrusion.', 'Mettre en place les moyens de protection collective en dotation.', 'Supprimer immédiatement, si possible de façon permanente, les dangers environnants (éviter le suraccident).', 'En cas d’impossibilité ou de danger réel et imminent pour la victime : réaliser un dégagement d’urgence.'],
      stepsTitle: 'Démarche de protection', after: '<p class="small muted">Ces actions peuvent être menées simultanément selon les moyens humains disponibles (AC - Protection et sécurité).</p>' }
  ],
  key: ['Ordre immuable : circonstanciel → primaire → secondaire → surveillance.', 'Circonstanciel = prévention des dangers + « sont-ils maîtrisables ? ».', 'Danger réel et imminent non supprimable → dégagement d’urgence.', 'Le circonstanciel oriente la suite (ex. mécanisme → suspicion de traumatisme du rachis).'],
  traps: ['Se précipiter sur la victime sans avoir regardé la scène : risque de suraccident.', 'Oublier de compter les victimes : la demande de renfort doit être précoce.'],
  quiz: [
    { q: 'Quel bilan est réalisé en premier, à la présentation sur intervention ?', c: ['Le bilan circonstanciel', 'Le bilan primaire', 'Le bilan secondaire', 'Le bilan de surveillance'], e: 'Le circonstanciel précède le contact avec la victime : il vise la prévention des dangers.', s: 'chaine' },
    { q: 'Les deux questions clés du bilan circonstanciel sont :', c: ['Quels dangers (intervenants, entourage, victimes) ? Sont-ils maîtrisables ?', 'La victime respire-t-elle ? A-t-elle un pouls ?', 'Quels sont ses antécédents ? Ses allergies ?', 'Quelle est la SpO₂ ? Quelle est la glycémie ?'], e: 'PR - Bilan circonstanciel : prévention des dangers, puis « les dangers sont-ils maîtrisables ? ».', s: 'circonstanciel' },
    { q: 'Un danger réel et imminent menace la victime et ne peut pas être supprimé. Que fait-on ?', c: ['Un dégagement d’urgence', 'Un bilan secondaire complet sur place', 'On attend l’arrivée d’un médecin', 'On réalise une immobilisation complète avant tout déplacement'], e: 'AC - Protection et sécurité : en cas d’impossibilité ou de danger réel et imminent, réaliser un dégagement d’urgence.', s: 'circonstanciel' },
    { q: 'Quel est l’ordre correct des bilans ?', c: ['Circonstanciel → primaire → secondaire → surveillance', 'Primaire → circonstanciel → secondaire → surveillance', 'Circonstanciel → secondaire → primaire → surveillance', 'Primaire → secondaire → circonstanciel → surveillance'], e: 'Schéma chronologique de la PR - Bilan secondaire.', s: 'chaine' }
  ]
});

VSAV.chap({
  id: 'bilan-primaire', part: 'foad', seq: 'FOAD 1.1 — Les bilans', title: 'Le bilan primaire XABCDE', short: 'Bilan primaire XABCDE',
  motif: 'target', sources: ['PR - Bilan primaire (MAJ 05/2024)', 'Mémento SSUAP', 'Mémos B, C, D (A6)'],
  summary: 'Rechercher en quelques instants une détresse vitale et la traiter avant toute autre action.',
  why: '<b>Pourquoi XABCDE ?</b> Le bilan primaire suit <b>le chemin de la molécule d’oxygène</b> dans l’organisme : il faut du sang pour la transporter (X), un passage libre pour qu’elle entre (A), une mécanique respiratoire pour l’amener aux poumons puis aux globules rouges (B), une circulation pour la distribuer (C), un cerveau qui l’utilise (D), et un corps protégé du froid et des lésions cachées (E). Si un maillon casse, tous les suivants sont inutiles : c’est pourquoi on <b>traite en premier ce qui tue en premier</b>, et on initie les gestes de survie <b>avant</b> de passer à l’item suivant.',
  sections: [
    { id: 'principe', t: 'But et principe', ic: 'bulb', src: 'PR - Bilan primaire, p. 1',
      html: '<ul class="check"><li>Rechercher une <b>détresse vitale</b> qui menace immédiatement la vie et nécessite des gestes de secours avant toute autre action.</li><li>Permettre au chef d’agrès de <b>catégoriser</b> la victime : Urgence Absolue (UA), Urgence Relative (UR), Impliqué (IMP).</li><li>C’est une aide au raisonnement et à la priorisation des gestes.</li></ul><div class="callout warn"><b>Victime en urgence absolue</b>Le chef d’agrès contacte immédiatement le CRRA 15 pour demander un renfort médical.</div>',
      figs: [{ anim: 'xabcde', cap: 'Animation : la molécule d’O₂ traverse X, A, B, C, D, E', txt: '<p>Pour chaque lettre : l’objectif et les gestes urgents tirés de la fiche.</p>', src: 'PR - Bilan primaire' }, { img: 'img/fiches/xabcde.jpg', cap: 'Schéma de la fiche : moyen mnémotechnique XABCDE', txt: '<p>Le schéma officiel relie chaque lettre à un organe : sang (X), voies aériennes (A), poumons (B), cœur et vaisseaux (C), cerveau (D), environnement (E).</p>', src: 'PR - Bilan primaire, p. 2' }] },
    { id: 'x', t: 'X — Hémorragie externe', ic: 'drop', src: 'PR - Bilan primaire, p. 3',
      html: '<p><b>Objectif :</b> stopper et maintenir en permanence l’arrêt de l’hémorragie.</p><p>On débute par une <b>observation globale</b> à la recherche d’une hémorragie visible, qui entraîne immédiatement une technique d’arrêt du saignement selon la procédure : compression manuelle, pansement compressif type israélien, garrot tourniquet, pansement hémostatique.</p><p>Voir le chapitre <a href="#/c/hemorragies">Hémorragies externes</a>.</p>' },
    { id: 'a', t: 'A — Airway : voies aériennes et rachis cervical', ic: 'lungs', src: 'PR - Bilan primaire, p. 3',
      html: '<p><b>Objectif :</b> maintenir en permanence la liberté des voies aériennes <b>et</b> la stabilisation du rachis cervical. Une victime qui parle correctement a les voies aériennes libres et perméables.</p><p><b>Conduite :</b> maintien de la tête (stabilisation), puis appréciation de la liberté des voies aériennes ; le geste de LVA est adapté à une éventuelle suspicion traumatique relevée au bilan circonstanciel (bascule de la tête en arrière ou élévation du menton).</p>' +
        '<div class="tw"><table><tr><th>Situation</th><th>Geste urgent</th></tr><tr><td>Inconscient sur le ventre</td><td>Retournement d’urgence</td></tr><tr><td>OBVA / suffocation complète</td><td>Technique de désobstruction</td></tr><tr><td>Lien constrictif autour du cou</td><td>Relâchement du lien</td></tr><tr><td>Obstacle externe (casque intégral)</td><td>Retrait de casque</td></tr><tr><td>Ronflement ou apnée ; inconscient sur le dos</td><td>Libération des voies aériennes adaptée</td></tr><tr><td>Corps étranger visible</td><td>Extraction digitale</td></tr><tr><td>VAS menacées par des liquides (sang, vomissures)</td><td>Aspiration</td></tr></table></div><p class="small muted">La stabilisation du rachis cervical est relâchée en fonction de l’algorithme décisionnel d’immobilisation du rachis.</p>' },
    { id: 'b', t: 'B — Breathing : ventilation', ic: 'lungs', src: 'PR - Bilan primaire, p. 4 · Memo B',
      html: '<p><b>Objectif :</b> s’assurer de l’efficacité de la respiration. Le mouvement ventilatoire (soulèvement du thorax) doit être <b>ample, régulier et symétrique</b>.</p><p><b>Appréciation sur 10 secondes</b> : respiration normale, efficace ou agonique ? fréquence, amplitude, rythme, symétrie (si inconscient, prendre le pouls en simultané). Exposer le thorax : hématome, emphysème sous-cutané, plaie (soufflante…). Saturation à l’air ambiant (sans retarder les gestes). Bruits ventilatoires anormaux.</p>' +
        '<div class="tw"><table><tr><th>Constat</th><th>Conduite</th></tr><tr><td>Pas de ventilation, ou ventilation inefficace / agonique (amplitude faible et fréquence lente ≤ 6 mvts/min)</td><td>Prise de pouls simultanée ; en son absence, débuter la RCP ; insufflations au BAVU</td></tr><tr><td>SpO₂ &lt; 94 %</td><td>Inhalation au MHC, débit initial 15 L/min puis ajuster de 9 à 15 L/min — objectif 94 à 98 %</td></tr><tr><td>IRC : SpO₂ &lt; 89 %</td><td>Débit initial 15 L/min puis 9 à 15 L/min — objectif 89 à 92 %</td></tr><tr><td>Signes de détresse respiratoire</td><td>O₂ au MHC quelle que soit la SpO₂ ; position d’attente adaptée</td></tr></table></div>' },
    { id: 'c', t: 'C — Circulation et saignement', ic: 'heart', src: 'PR - Bilan primaire, p. 5 · Memo C',
      html: '<p><b>Objectif :</b> rechercher les signes d’une défaillance circulatoire. Une bonne oxygénation des globules rouges ne sert à rien s’ils ne perfusent pas les organes.</p><ul class="check"><li>Détecter et contrôler d’abord une hémorragie externe, puis apprécier l’état circulatoire.</li><li><b>Sur 10 secondes</b> : pouls périphérique (radial) ? sinon pouls central (carotidien, fémoral) ? fréquence, amplitude, rythme, symétrie.</li><li>Temps de recoloration cutanée (TRC) ; aspect de la peau : pâleur, marbrures, extrémités froides, sueurs abondantes et persistantes.</li><li>Une détresse circulatoire doit faire rechercher une <b>hémorragie interne</b> : observer et palper les <b>« boîtes à sang »</b> (thorax, abdomen, bassin, cuisses).</li></ul>' +
        '<div class="tw"><table><tr><th>Constat</th><th>Conduite</th></tr><tr><td>Arrêt cardio-respiratoire</td><td>RCP + pose du défibrillateur</td></tr><tr><td>Gestes du X déjà réalisés</td><td>Contrôler l’efficacité de l’arrêt du saignement, ajuster si besoin</td></tr><tr><td>Signes de détresse circulatoire</td><td>O₂ au MHC quelle que soit la SpO₂, position d’attente adaptée</td></tr></table></div>' },
    { id: 'd', t: 'D — Disability : déficit neurologique', ic: 'brain', src: 'PR - Bilan primaire, p. 6 · Memo D · Mémento',
      html: '<p><b>Objectif :</b> évaluer la fonction cérébrale, mesure indirecte de l’oxygénation du cerveau — une fois l’apport et la distribution d’O₂ corrigés autant que possible.</p><ul class="check"><li>Score de Glasgow (3 à 15).</li><li>Pupilles : diamètre, symétrie, réactivité.</li><li>Motricité et sensibilité des 4 membres.</li><li><b>Glycémie capillaire si trouble de la conscience.</b></li><li>Convulsions répétitives ?</li></ul><div class="tw"><table><tr><th>Constat</th><th>Conduite</th></tr><tr><td>Déficit / trouble de la conscience</td><td>Mesure de la glycémie capillaire</td></tr><tr><td>Signes de détresse neurologique</td><td>O₂ suivant la saturation</td></tr><tr><td>Glasgow &lt; 8</td><td>Présence médicale recommandée (prise en compte des voies aériennes supérieures)</td></tr><tr><td>—</td><td>Position d’attente adaptée (ex. PLS à 2 secouristes)</td></tr></table></div>',
      figs: [{ anim: 'glasgow', cap: 'Calculateur de Glasgow', txt: '<p>Y (4) + V (5) + M (6) : de 3 à 15. Choisis les réponses pour t’entraîner à chiffrer.</p>', src: 'Mémento SSUAP · Mémo D' }] },
    { id: 'e', t: 'E — Exposition et environnement', ic: 'snow', src: 'PR - Bilan primaire, p. 7',
      html: '<p><b>Objectif :</b> s’assurer qu’il n’y a pas de lésion vitale cachée et lutter contre l’hypo- ou l’hyperthermie. Sur le terrain, n’exposer que l’essentiel : <b>on découvre, on regarde, on recouvre</b> ; le déshabillage se poursuit au chaud, à l’abri des regards.</p><ul class="check"><li>Hypothermie (T° &lt; 35 °C) ? Hyperthermie (T° &gt; 40 °C) avec trouble de la conscience (coup de chaleur) ?</li><li>Brûlure grave ? Traumatisme pénétrant dans une zone critique (tête, cou, tronc, racine des membres) ? Section de membre ?</li></ul><p><b>Gestes :</b> couvrir de façon adaptée et efficace, refroidir si besoin, extraire rapidement du milieu hostile, <b>lutter contre la triade létale</b>.</p>',
      figs: [{ svg: 'hypothermie', cap: 'Gravité de l’hypothermie', txt: '<p>Classement de la fiche selon la température centrale.</p>', src: 'PR - Bilan primaire, p. 7' }] }
  ],
  key: ['XABCDE = chemin de la molécule d’O₂ ; traiter ce qui tue en premier.', 'Gestes de survie initiés pour chaque item AVANT de passer au suivant.', 'Appréciations B et C sur <b>10 secondes</b> (bilan secondaire : 1 minute).', 'Ventilation agonique : ≤ 6 mvts/min → pouls ; absent → RCP.', 'SpO₂ &lt; 94 % → MHC 15 L/min puis 9–15 L/min (94–98 %) ; IRC &lt; 89 % → 89–92 %.', 'Détresse respiratoire ou circulatoire → O₂ quelle que soit la SpO₂ ; neurologique → selon la SpO₂.', 'Trouble de conscience → glycémie capillaire ; Glasgow &lt; 8 → présence médicale.', 'Boîtes à sang : thorax, abdomen, bassin, cuisses.'],
  memo: ['X A B C D E : sang · air · ventilation · circulation · cerveau · exposition', 'B et C appréciés sur 10 s', 'Agonique ≤ 6/min → RCP si pas de pouls', 'O₂ : &lt; 94 % → 15 puis 9–15 L/min (94–98 %) ; IRC &lt; 89 % → 89–92 %', 'Boîtes à sang : thorax, abdomen, bassin, cuisses', 'Glasgow &lt; 8 → médecin ; trouble conscience → glycémie', 'UA → CRRA 15 immédiatement (chef d’agrès)'],
  traps: ['Passer au B alors que l’hémorragie du X n’est pas contrôlée.', 'Faire basculer la tête d’une victime suspecte de traumatisme : on élève le menton.', 'Attendre la SpO₂ pour oxygéner une détresse respiratoire ou circulatoire : c’est « quelle que soit la SpO₂ ».', 'Déshabiller entièrement la victime dehors : on découvre, on regarde, on recouvre.'],
  quiz: [
    { q: 'Que représente la lettre X du bilan primaire ?', c: ['La recherche et l’arrêt d’une hémorragie externe visible', 'L’examen des radiographies', 'L’exposition au froid', 'Le contrôle de la glycémie'], e: 'X permet de stopper une diminution du volume sanguin : hémorragie visible → technique d’arrêt du saignement immédiate.', s: 'x' },
    { q: 'Sur quelle durée apprécie-t-on la ventilation lors du bilan primaire ?', c: ['10 secondes', '1 minute', '30 secondes', '5 minutes'], e: 'Bilan primaire : appréciation sur 10 s ; bilan secondaire : évaluation sur 1 min (Memo B).', s: 'b' },
    { q: 'Victime adulte (non IRC) sans détresse, SpO₂ = 91 %. Quel débit d’O₂ initial ?', c: ['15 L/min au MHC, puis ajuster de 9 à 15 L/min pour 94–98 %', '3 L/min aux lunettes', 'Pas d’oxygène tant que la victime parle', '6 L/min au masque simple, objectif 89–92 %'], e: 'SpO₂ < 94 % : débit initial 15 L/min puis ajustement de 9 à 15 L/min, objectif 94 à 98 %.', s: 'b' },
    { q: 'Victime présentant des signes de détresse circulatoire, SpO₂ = 97 %. Oxygène ?', c: ['Oui, au MHC, quelle que soit la SpO₂', 'Non, la SpO₂ est normale', 'Oui, mais seulement si IRC', 'Uniquement sur avis médical'], e: 'Détresse respiratoire ou circulatoire : mise sous O₂ quelle que soit la SpO₂ (Memo B, PR Bilan primaire).', s: 'c' },
    { q: 'Que sont les « boîtes à sang » ?', c: ['Thorax, abdomen, bassin, cuisses', 'Crâne, cou, bras, jambes', 'Cœur, poumons, foie, rate', 'Mains, pieds, visage, cou'], e: 'Zones anatomiques critiques à observer et palper à la recherche d’une hémorragie interne.', s: 'c' },
    { q: 'Que faire devant un trouble de la conscience lors du D ?', c: ['Mesurer la glycémie capillaire', 'Faire boire la victime', 'Lui donner du sucre d’emblée', 'Retirer le collier cervical'], e: 'PR Bilan primaire (D) : glycémie capillaire si trouble de la conscience.', s: 'd' },
    { q: 'Score de Glasgow < 8 : que recommande la fiche ?', c: ['Une présence médicale pour la prise en compte des voies aériennes', 'Un transport assis', 'Une RCP immédiate', 'Un resucrage systématique'], e: 'Glasgow < 8 : présence médicale recommandée (intubation, dispositif invasif de ventilation…).', s: 'd' },
    { q: 'Le principe du E se résume par :', c: ['On découvre, on regarde, on recouvre', 'On déshabille entièrement sur place', 'On ne touche pas aux vêtements', 'On réchauffe toujours activement'], e: 'Exposer uniquement les parties essentielles pour ne pas induire ou majorer une hypothermie.', s: 'e' },
    { q: 'Une victime hypotherme à 30 °C présente une hypothermie :', c: ['Modérée', 'Légère', 'Sévère', 'Profonde'], e: '32 > T° > 28 °C : modérée. 35–32 légère, 28–24 sévère, < 24 profonde.', s: 'e' }
  ]
});

VSAV.chap({
  id: 'bilan-secondaire', part: 'foad', seq: 'FOAD 1.1 — Les bilans', title: 'Le bilan secondaire', short: 'Bilan secondaire',
  motif: 'clip', sources: ['PR - Bilan secondaire (MAJ 05/2024)', 'Mémento SSUAP', 'Mémos B, C, D (A6)'],
  summary: 'Chiffrer chaque fonction vitale, interroger, examiner de la tête aux pieds.',
  why: '<b>Pourquoi un second bilan ?</b> Le primaire a écarté ce qui tue à court terme. Le secondaire sert à <b>détailler et chiffrer</b> fonction par fonction (pour pouvoir comparer ensuite lors de la surveillance), à trouver les lésions passées inaperçues grâce à un examen région par région, et à comprendre l’histoire de la victime (OPQRST, SAMPLER) pour transmettre un bilan utile au médecin régulateur.',
  sections: [
    { id: 'contenu', t: 'Ce que comporte le bilan secondaire', ic: 'list', src: 'PR - Bilan secondaire, p. 1',
      html: '<ul class="check"><li>La mesure des constantes vitales.</li><li>L’interrogatoire.</li><li>L’examen complet de la victime (tête aux pieds).</li><li>Le soutien d’un traumatisme en attente d’une immobilisation.</li><li>La prise en charge d’une pathologie, maladie…</li></ul>' },
    { id: 'bcd', t: 'B, C, D chiffrés', ic: 'ecg', src: 'PR - Bilan secondaire, p. 2–3 · Mémos B, C, D',
      html: '<h3>B — Ventilation (sur 1 minute)</h3><p>Fréquence, rythme (régulier ou non), amplitude (efficace ou superficielle), symétrie ; SpO₂ (air ambiant / sous O₂). Signes associés : difficulté à parler (aptitude à compter &lt; 6), sueurs, cyanose, bruits anormaux (sifflement, gargouillement, râles), pincement des ailes du nez (enfant, nourrisson), tirage, contraction des muscles du haut du thorax et du cou, balancement thoraco-abdominal, somnolence.</p>' +
        '<h3>C — Circulation (sur 1 minute)</h3><p>Fréquence, rythme, amplitude (bien frappé / filant), symétrie ; TRC ; aspect de la peau ; <b>prise de la tension artérielle</b> (aux 2 bras si nécessaire).</p><div class="callout warn"><b>Seuil du TRC : deux valeurs dans les documents</b>La PR Bilan secondaire indique « détresse circulatoire si supérieur à 3 secondes » ; le Memo C (A6) indique « › à 2 secondes ». Retiens la règle de ton centre de formation et signale l’écart à ton formateur.</div>' +
        '<h3>D — Neurologique</h3><p>Surveillance de l’AVPU (amélioration / dégradation), pupilles, agitation, perte de connaissance initiale (PCI), convulsions, paralysie faciale / hémiplégie, troubles de la parole et de l’équilibre. Suspicion d’AVC → <b>FAST</b> (Face, Arm, Speech, Time).</p>' +
        '<div class="tw"><table><tr><th></th><th>Adulte</th><th>Enfant</th><th>Nourrisson</th><th>Nouveau-né</th></tr><tr><td>Âge</td><td>à partir de la puberté</td><td>1 an à la puberté</td><td>1 semaine à 1 an</td><td>moins d’1 semaine</td></tr><tr><td>FR (mvts/min)</td><td>12 à 20</td><td>20 à 30</td><td>30 à 40</td><td>40 à 60</td></tr><tr><td>FC (bat/min)</td><td>60 à 100</td><td>70 à 140</td><td>100 à 160</td><td>120 à 160</td></tr></table></div><p class="small muted">Source : Mémento SSUAP.</p>' +
        '<div class="tw"><table><tr><th>AVPU (anglais)</th><th>EVDA (français)</th><th>Niveau</th></tr><tr><td>A — Alert</td><td>E — Éveillé</td><td>Consciente de ce qui se passe autour d’elle</td></tr><tr><td>V — Verbal</td><td>V — Voix</td><td>Répond aux commandes verbales</td></tr><tr><td>P — Pain</td><td>D — Douleur</td><td>Réagit aux stimuli douloureux</td></tr><tr><td>U — Unresponsive</td><td>A — Aucune</td><td>Ne réagit pas aux stimuli douloureux</td></tr></table></div>' },
    { id: 'e', t: 'E — Examen de la tête aux pieds', ic: 'eye', src: 'PR - Bilan secondaire, p. 4–5',
      html: '<p>Rechercher une pathologie particulière, palper de la tête aux pieds, questionner sur l’origine des plaintes. Pour chaque région (tête, cou, thorax, abdomen, dos, membres supérieurs et inférieurs avec motricité / sensibilité / pouls) : <b>regarder, palper, écouter, sentir</b>.</p><p>Signes recherchés : contusion, plaie / dermabrasion / écorchure, brûlure, douleur, saignement caché, déformation, fracture ouverte, œdème.</p><ul class="check"><li>Identifier et traiter les lésions ; mesurer la température ; chiffrer la glycémie selon la situation.</li><li>Quantifier la surface des brûlures (<b>score de Wallace</b>) et les protéger.</li><li>Soutenir les membres blessés dans l’attente d’une immobilisation ; protéger et panser les plaies ; préparer au transport.</li></ul>',
      figs: [{ img: 'img/fiches/wallace.jpg', cap: 'Schéma de la fiche : score de Wallace, glycémie, OPQRST', txt: '<p>La règle de Wallace (face antérieure / postérieure) sert à estimer la surface brûlée.</p>', src: 'PR - Bilan secondaire, p. 4' }] },
    { id: 'interrogatoire', t: 'L’interrogatoire : OPQRST et SAMPLER', ic: 'psy', src: 'PR - Bilan secondaire, p. 4 et 6 · Mémento',
      html: '<div class="grid g2"><div class="card"><h3>OPQRST — la plainte</h3><ul><li><b>O</b>rigine : début de l’épisode</li><li><b>P</b>rovoqué par : mécanisme de l’accident</li><li><b>Q</b>ualité de la douleur : analyser la plainte</li><li><b>R</b>égion douloureuse</li><li><b>S</b>évérité : évaluer la douleur</li><li><b>T</b>emps</li></ul></div><div class="card"><h3>SAMPLER — les antécédents (F)</h3><ul><li><b>S</b>ymptômes et signes associés</li><li><b>A</b>llergies</li><li><b>M</b>édicaments</li><li><b>P</b>assé médico-chirurgical</li><li><b>L</b>ast meal (dernier repas)</li><li><b>E</b>vénements ayant entraîné l’urgence</li><li><b>R</b>isques : antécédents familiaux, facteurs aggravants (obésité, sédentarité…), toxiques (alcool, stupéfiants, tabac)</li></ul></div></div><p class="small muted">Le SAMPLER est plus complet que le MHTA (PR - Bilan secondaire, item F « Familiar »).</p>' }
  ],
  key: ['Secondaire : constantes chiffrées <b>sur 1 minute</b>, interrogatoire, examen tête-pieds.', 'Normes adulte : FR 12–20, FC 60–100 ; enfant FR 20–30, FC 70–140 ; nourrisson FR 30–40, FC 100–160 ; nouveau-né FR 40–60, FC 120–160.', 'Tension artérielle aux 2 bras si nécessaire.', 'Examen : regarder, palper, écouter, sentir.', 'OPQRST pour la plainte, SAMPLER pour les antécédents.', 'Brûlures : score de Wallace.', 'Suspicion d’AVC : FAST.'],
  traps: ['Confondre durées : 10 s au primaire, 1 min au secondaire.', 'Oublier le dos et la symétrie (pouls, mouvements thoraciques).', 'TRC : la PR Bilan secondaire dit > 3 s, le Memo C dit > 2 s — connaître l’écart.'],
  quiz: [
    { q: 'Sur quelle durée la fréquence respiratoire est-elle évaluée au bilan secondaire ?', c: ['1 minute', '10 secondes', '15 secondes', '2 minutes'], e: 'Bilan secondaire : évaluation sur 1 min (Memo B).', s: 'bcd' },
    { q: 'Fréquence respiratoire normale d’un adulte :', c: ['12 à 20 mvts/min', '20 à 30 mvts/min', '30 à 40 mvts/min', '6 à 10 mvts/min'], e: 'Mémento SSUAP : adulte 12–20, enfant 20–30, nourrisson 30–40, nouveau-né 40–60.', s: 'bcd' },
    { q: 'Fréquence cardiaque normale d’un nourrisson :', c: ['100 à 160 bat/min', '60 à 100 bat/min', '70 à 140 bat/min', '120 à 160 bat/min'], e: 'Nourrisson (1 semaine à 1 an) : 100–160. 120–160 = nouveau-né.', s: 'bcd' },
    { q: 'Dans SAMPLER, que signifie le « L » ?', c: ['Last meal : le dernier repas', 'Localisation de la douleur', 'Lésions associées', 'Liberté des voies aériennes'], e: 'S symptômes, A allergies, M médicaments, P passé, L last meal, E événements, R risques.', s: 'interrogatoire' },
    { q: 'Dans OPQRST, le « P » correspond à :', c: ['Provoqué par : rechercher le mécanisme', 'Pouls', 'Pupilles', 'Passé médical'], e: 'O origine, P provoqué par, Q qualité, R région, S sévérité, T temps.', s: 'interrogatoire' },
    { q: 'Quel score permet d’estimer la surface brûlée ?', c: ['Le score de Wallace', 'Le score de Glasgow', 'L’AVPU', 'Le FAST'], e: 'PR - Bilan secondaire : quantifier la surface des brûlures (score de Wallace).', s: 'e' },
    { q: 'Le « P » de l’AVPU signifie que la victime :', c: ['Réagit aux stimuli douloureux', 'Est parfaitement éveillée', 'Répond aux commandes verbales', 'Ne réagit à rien'], e: 'P = Pain (D = Douleur en français).', s: 'bcd' }
  ]
});

VSAV.chap({
  id: 'bilan-surveillance', part: 'foad', seq: 'FOAD 1.1 — Les bilans', title: 'Le bilan de surveillance', short: 'Bilan de surveillance',
  motif: 'clock', sources: ['PR - Bilan de surveillance (MAJ 05/2024)'],
  summary: 'Suivre l’évolution, vérifier l’efficacité des gestes, adapter la prise en charge.',
  why: '<b>Pourquoi surveiller en permanence ?</b> L’état d’une victime évolue : un geste efficace peut cesser de l’être (reprise d’un saignement, immobilisation qui se relâche), une détresse peut apparaître. Sans surveillance, la dégradation passe inaperçue. On compare les valeurs aux chiffres du bilan secondaire pour détecter une tendance.',
  sections: [
    { id: 'principe', t: 'Principe et moments', ic: 'clock', src: 'PR - Bilan de surveillance',
      html: '<p>La surveillance permet de <b>suivre l’évolution</b> de l’état de la victime, <b>d’évaluer l’efficacité</b> des gestes et <b>d’adapter</b> la prise en charge. Elle débute <b>dès la fin du bilan primaire et/ou secondaire</b> et est assurée <b>en permanence</b> jusqu’à la fin de la prise en charge. Sa non-réalisation peut entraîner une dégradation de l’état de la victime.</p>',
      figs: [{ svg: 'surveillance', cap: 'Rythme de contrôle des paramètres vitaux', txt: '<p>Détresse : toutes les <b>5 minutes au maximum</b>. Autres cas : toutes les <b>10 à 15 minutes</b>.</p>', src: 'PR - Bilan de surveillance' }] },
    { id: 'cat', t: 'Conduite à tenir', ic: 'list', src: 'PR - Bilan de surveillance',
      steps: ['Contrôler régulièrement la qualité de la respiration (FR, SpO₂) et l’état circulatoire (FC, PA).', 'Apprécier toute modification de l’état de conscience.', 'Rechercher une modification des plaintes.', 'Réconforter la victime en lui expliquant ce qui se passe.', 'Contrôler régulièrement l’efficacité des gestes : arrêt des hémorragies, qualité d’une immobilisation, protection contre le chaud, le froid…'],
      after: '<div class="callout bad"><b>Si l’état s’aggrave</b>Réaliser les gestes de secours adaptés, <b>refaire un bilan primaire</b> et transmettre un nouveau bilan à la régulation.</div>' }
  ],
  key: ['Surveillance dès la fin du primaire et/ou secondaire, en permanence.', 'Détresse : paramètres toutes les 5 min max ; sinon toutes les 10 à 15 min.', 'Aggravation → gestes adaptés + nouveau bilan primaire + nouveau bilan transmis.', 'Vérifier aussi l’efficacité des gestes (hémorragie, immobilisation, protection thermique).'],
  traps: ['Attendre l’hôpital pour reprendre les constantes.', 'Oublier de retransmettre un bilan en cas d’aggravation.'],
  quiz: [
    { q: 'À quelle fréquence contrôle-t-on les paramètres vitaux d’une victime en détresse ?', c: ['Toutes les 5 minutes au maximum', 'Toutes les 10 à 15 minutes', 'Toutes les 30 minutes', 'Uniquement à l’arrivée à l’hôpital'], e: 'PR - Bilan de surveillance : 5 min max en cas de détresse.', s: 'principe' },
    { q: 'Et pour une victime sans détresse ?', c: ['Toutes les 10 à 15 minutes', 'Toutes les 5 minutes au maximum', 'Toutes les heures', 'Jamais'], e: 'Dans les autres cas : 10 à 15 min.', s: 'principe' },
    { q: 'L’état de la victime s’aggrave pendant la surveillance. Que faire ?', c: ['Gestes adaptés, refaire un bilan primaire, transmettre un nouveau bilan', 'Continuer le transport sans rien changer', 'Refaire uniquement l’interrogatoire', 'Attendre la fin du transport pour transmettre'], e: 'Conduite prévue par la fiche en cas d’aggravation.', s: 'cat' },
    { q: 'Quand débute la surveillance ?', c: ['Dès la fin du bilan primaire et/ou secondaire', 'Uniquement dans le VSAV', 'Après le relevage', 'À l’arrivée du médecin'], e: 'Elle débute dès la fin du primaire et/ou secondaire et dure jusqu’à la fin de la prise en charge.', s: 'principe' }
  ]
});

VSAV.chap({
  id: 'snv', part: 'foad', seq: 'FOAD 1.2 — Situation nombreuses victimes', title: 'Repérage en cas de nombreuses victimes', short: 'Nombreuses victimes',
  motif: 'team', accent: '#0f766e', sources: ['FT - Repérage en cas de nombreuses victimes (MAJ 05/2024)'],
  summary: 'Catégoriser vite, avec des critères simples, pour prioriser quand les victimes graves sont plus nombreuses que les secouristes.',
  why: '<b>Pourquoi un repérage plutôt qu’un bilan complet ?</b> Quand le nombre de victimes apparemment graves dépasse le nombre de secouristes, passer dix minutes sur une victime en condamne d’autres. Le repérage permet en attendant les renforts de <b>localiser</b> les victimes, de réaliser les <b>gestes immédiats</b> (garrot, LVA, position d’attente) et de désigner celles que le médecin doit voir <b>en priorité</b>.',
  sections: [
    { id: 'quand', t: 'Quand et avec quoi ?', ic: 'team', src: 'FT - Repérage en cas de nombreuses victimes',
      html: '<p>Dès qu’on est en présence de plusieurs victimes et que le nombre de victimes apparemment graves est <b>supérieur au nombre de secouristes</b>.</p><p>Matériel : fiches d’identification, bracelets… (numérotation unique tout au long de la chaîne), code couleur ; à défaut, marquage au stylo.</p>' },
    { id: 'methode', t: 'La méthode et les couleurs', ic: 'target', src: 'FT - Repérage en cas de nombreuses victimes',
      html: '<p>Aborder les victimes <b>les unes après les autres en commençant par la plus proche</b>, réaliser un <b>bilan primaire succinct</b>.</p><div class="tw"><table><tr><th>Couleur</th><th>Victime</th><th>Action</th></tr><tr><td><span class="tag-col" style="background:#111">NOIRE</span></td><td>Décès sans aucun doute (tête séparée du tronc, déchiquetée, démembrée, raideur cadavérique) ; ou inconsciente qui ne respire pas après LVA</td><td>Ne pas déplacer ; fiche d’identification. RCP seulement à la demande du médecin ou sur ordre du responsable si toutes les victimes sont prises en charge.</td></tr><tr><td><span class="tag-col" style="background:#c0262d">ROUGE</span></td><td>Inconsciente qui respire ; ou consciente avec détresse vitale évidente (FR &gt; 30/min ou FC &gt; 120/min chez l’adulte) ou hémorragie</td><td>PLS / geste adapté (garrot, pansement compressif, position d’attente) sans rester immobilisé auprès d’elle ; prise en charge médicale prioritaire, souvent sur place.</td></tr><tr><td><span class="tag-col" style="background:#d4a106">JAUNE</span></td><td>Consciente, sans détresse vitale, ne peut pas se déplacer</td><td>Aucun geste sur place ; prise en charge dès que possible (poste médical avancé).</td></tr><tr><td><span class="tag-col" style="background:#1a8a3d">VERTE</span></td><td>Consciente, sans détresse, se déplace seule ou avec aide</td><td>Diriger vers le Point de Rassemblement des Victimes (PRV), surveillance et examen médical ultérieur.</td></tr></table></div>',
      figs: [{ anim: 'triage', cap: 'Entraînement : l’arbre de repérage', txt: '<p>Réponds aux questions comme sur le terrain ; l’outil te donne la couleur et l’action.</p>', src: 'FT - Repérage en cas de nombreuses victimes' }] }
  ],
  key: ['Déclencheur : victimes graves plus nombreuses que les secouristes.', 'Commencer par la victime la plus proche ; bilan primaire succinct.', 'Noir : décès évident ou ne respire pas après LVA.', 'Rouge : inconsciente qui respire (PLS) ou détresse vitale (FR > 30, FC > 120 adulte, hémorragie).', 'Jaune : consciente, sans détresse, non valide. Vert : se déplace → PRV.', 'Les gestes ne doivent pas immobiliser le secouriste en permanence.'],
  traps: ['Débuter une RCP pendant le repérage : seulement sur demande médicale / ordre du responsable, toutes victimes prises en charge.', 'Rester fixé sur une victime au lieu de poursuivre le repérage.'],
  quiz: [
    { q: 'Victime inconsciente qui respire après LVA : quelle couleur ?', c: ['Rouge (après mise en PLS)', 'Noire', 'Jaune', 'Verte'], e: 'Inconsciente qui respire : PLS, fiche, couleur ROUGE.', s: 'methode' },
    { q: 'Victime inconsciente qui ne respire pas après LVA :', c: ['Noire', 'Rouge', 'Jaune', 'Verte'], e: 'Elle est identifiée NOIRE ; la réanimation n’est débutée que sur demande médicale ou ordre, toutes victimes prises en charge.', s: 'methode' },
    { q: 'Quels critères définissent une détresse vitale évidente chez l’adulte conscient ?', c: ['FR > 30/min ou FC > 120/min', 'FR > 20/min ou FC > 100/min', 'SpO₂ < 94 %', 'Glasgow < 13'], e: 'Critères de la FT : FR > 30/min ou FC > 120/min chez l’adulte.', s: 'methode' },
    { q: 'Victime consciente, sans détresse, qui marche : que fait-on ?', c: ['Couleur verte et direction le Point de Rassemblement des Victimes', 'Couleur jaune et poste médical avancé immédiat', 'Couleur rouge et PLS', 'On la laisse repartir'], e: 'VERTE : la diriger vers le PRV, à l’écart du sinistre.', s: 'methode' },
    { q: 'Par quelle victime commence le repérage ?', c: ['La plus proche de l’endroit où l’on se trouve', 'La plus jeune', 'Celle qui crie le plus', 'La plus éloignée'], e: 'Aborder les victimes une à une en commençant par la plus proche.', s: 'methode' }
  ]
});

VSAV.chap({
  id: 'roles', part: 'foad', seq: 'FOAD 1.3 — Cadre juridique', title: 'Rôles et compétences de l’équipier secouriste', short: 'Rôles et compétences',
  motif: 'shield', sources: ['AC - Rôles et compétences (MAJ 05/2024)'],
  summary: 'Attitude, impact psychologique de l’événement, abord relationnel et secret professionnel.',
  why: '<b>Pourquoi parler d’attitude dans une formation technique ?</b> La victime juge le secouriste autant sur la qualité de ses gestes que sur la relation humaine. Une parole ou un comportement maladroit peut suffire à dégrader une intervention ; une attitude calme et respectueuse favorise l’adhésion de la victime à toute sa prise en charge. L’empathie est présentée comme une <b>compétence professionnelle</b>, pas seulement une qualité.',
  sections: [
    { id: 'victimes', t: 'Victimes primaires et secondaires', ic: 'team', src: 'AC - Rôles et compétences',
      html: '<p>Le secouriste dispense aussi les <b>premiers secours psychologiques</b>. Il prend en compte :</p><ul class="check"><li><b>Les victimes primaires</b>, directement exposées : comme sujet (avoir subi), acteur (avoir provoqué) ou témoin (avoir vu). Blessures physiques et/ou psychologiques.</li><li><b>Les victimes secondaires</b> : les proches (parents, amis, collègues) qui découvrent ce qui est arrivé et ressentent un stress intense.</li></ul>' },
    { id: 'stress', t: 'La réaction de stress', ic: 'psy', src: 'AC - Rôles et compétences',
      html: '<p>Face à une situation soudaine et menaçante, toute personne présente une <b>réaction de stress</b> : moyen de défense utile, adaptatif mais bref et très coûteux en énergie (euphorie puis épuisement une fois la menace écartée).</p><ul><li>Signes physiques : hausse de la FR, de la FC et de la pression artérielle, frissons, tremblements, pâleur, « boule dans la gorge », « nœud à l’estomac », maux de tête, nausées, envie impérieuse d’uriner, gestes lents ou imprécis, voix altérée.</li><li>Signes psychologiques : incitation à l’action, focalisation sur le danger ; parfois vécu d’irréalité, tension.</li></ul><p>Quand le stress est trop intense, prolongé ou chronique, il devient <b>incapacitant</b> : la victime n’arrive plus à s’adapter et entre en <b>état de crise</b> (voir chapitre suivant). Plus l’impact est important, plus le risque de blessure psychologique est élevé : orientation vers une prise en charge spécialisée (urgences, <b>CUMP</b> en cas de nombreuses victimes).</p>' },
    { id: 'attitude', t: 'Comportement et abord relationnel', ic: 'hand', src: 'AC - Rôles et compétences',
      html: '<ul class="check"><li>Organisation, rigueur, professionnalisme ; tenue propre et correcte, bonne hygiène (première impression primordiale).</li><li>Calme, humanité, courtoisie ; respect des personnes et des lieux (meubles, bibelots…) ; respect de la vie privée.</li><li><b>Secret professionnel</b> : les informations ne sont transmises qu’aux personnes contribuant à la prise en charge.</li><li>C’est au secouriste de s’adapter à la victime, vulnérable.</li></ul><h3>Principes de communication</h3><ul><li>S’adresser toujours directement à la victime, quel que soit son âge.</li><li>« Juste distance » interpersonnelle ; se placer à son niveau, la regarder dans les yeux.</li><li>Vocabulaire et ton adaptés, phrases courtes, claires et respectueuses.</li><li>Vouvoiement et nom de famille pour l’adulte ; tutoiement et prénom pour l’enfant.</li><li>Le toucher manifeste soutien, réconfort et présence.</li></ul>' }
  ],
  key: ['Victime primaire : sujet, acteur ou témoin ; secondaire : proches.', 'Réaction de stress = défense utile mais brève et coûteuse.', 'Stress dépassé → état de crise ; orientation possible vers la CUMP.', 'Secret professionnel : comme les personnels de santé.', 'Vouvoiement + nom (adulte), tutoiement + prénom (enfant).'],
  traps: ['Ne s’adresser qu’aux parents quand la victime est un enfant : on parle directement à la victime.', 'Divulguer des informations à des tiers non impliqués dans la prise en charge.'],
  quiz: [
    { q: 'Un témoin direct d’un accident est une victime :', c: ['Primaire', 'Secondaire', 'Il n’est pas une victime', 'Tertiaire'], e: 'Victimes primaires : exposées comme sujet, acteur ou témoin.', s: 'victimes' },
    { q: 'Les proches qui apprennent l’accident sont des victimes :', c: ['Secondaires', 'Primaires', 'Impliquées en urgence absolue', 'Aucune des réponses'], e: 'Victimes secondaires : proches non confrontés directement à l’événement.', s: 'victimes' },
    { q: 'Comment s’adresse-t-on à un enfant victime ?', c: ['Directement, en le tutoyant et en l’appelant par son prénom', 'Uniquement via ses parents', 'En le vouvoyant et par son nom', 'On évite de lui parler'], e: 'AC - Rôles et compétences : tutoiement et prénom pour un enfant, toujours s’adresser à la victime.', s: 'attitude' },
    { q: 'Les informations recueillies sur intervention peuvent être divulguées :', c: ['Uniquement aux personnes contribuant à la prise en charge', 'À la famille élargie et aux voisins', 'À la presse si elle le demande', 'Sans restriction'], e: 'Le secouriste est tenu au secret professionnel.', s: 'attitude' }
  ]
});

VSAV.chap({
  id: 'crise', part: 'foad', seq: 'FOAD 1.5 — Souffrances psychiques et comportements inhabituels', title: 'Les personnes en situation de crise', short: 'Situation de crise',
  motif: 'psy', sources: ['AC - Les personnes en situation de crise (MAJ 05/2024)'],
  summary: 'Repérer un état de crise, en chercher la cause (souvent physique !) et reconnaître les réactions « silencieuses » et « bruyantes ».',
  why: '<b>Pourquoi est-ce un enjeu de secourisme ?</b> Un état de crise <b>prend souvent l’allure d’un trouble psychiatrique alors qu’il peut exprimer un problème physique</b> : hypoglycémie, hypoxie, AVC, traumatisme crânien, intoxication… Ne pas le reconnaître, c’est passer à côté d’une urgence vitale. C’est aussi une situation à risque pour l’équipe (agressivité, passage à l’acte).',
  sections: [
    { id: 'definition', t: 'Définition et causes', ic: 'psy', src: 'AC - Les personnes en situation de crise',
      html: '<p>La crise est une <b>manifestation brusque et intense, de durée limitée</b>, révélatrice d’une rupture d’équilibre et d’une souffrance aiguë difficile à contenir. Elle peut se traduire par un contact impossible, une agitation extrême, un état d’ébriété, un délire, des hallucinations, une angoisse massive, de l’agressivité, une violence incontrôlable ou des intentions suicidaires. La demande vient souvent de l’entourage.</p><p><b>Déclencheur externe</b> (événement stressant ou traumatisant : AVP, violence, catastrophe) ou <b>interne</b> (dysfonctionnement physique ou psychiatrique).</p><div class="tw"><table><tr><th>Famille</th><th>Exemples cités</th></tr><tr><td>Troubles organiques</td><td>Hypoglycémie, hypoxie, hypo/hyperthermie, déshydratation, tumeur cérébrale, AVC…</td></tr><tr><td>Traumatismes physiques</td><td>Crânien, hémorragie grave, douleur intense</td></tr><tr><td>Intoxications</td><td>Alcool, stupéfiants, médicaments (arrêt brutal, surdosage, interactions), souvent associés</td></tr><tr><td>Troubles psychiatriques</td><td>États aigus (transitoires, parfois révélateurs) ; états chroniques (schizophrénie, troubles bipolaires, du comportement alimentaire, addictifs…)</td></tr></table></div>' },
    { id: 'risques', t: 'Risques pour l’équipe et signes à observer', ic: 'alert', src: 'AC - Les personnes en situation de crise',
      html: '<p>Le secouriste risque d’être confronté à une attitude opposante, de l’agressivité voire de la violence, à un passage à l’acte sur soi ou autrui, et peut devoir <b>se retirer par mesure conservatoire</b>.</p><p>Observer : la présentation (vêtements, hygiène, marques), les signes physiques de stress (hyperventilation, pâleur, sueurs, tremblements), le comportement (hypo- ou hyperactivité, agressivité), le discours (accéléré, incohérent, amnésie, désorientation, idées suicidaires), l’état émotionnel (cris, pleurs, peur intense, colère, absence d’émotion, désespoir).</p>' },
    { id: 'reactions', t: 'Réactions « silencieuses » et « bruyantes »', ic: 'eye', src: 'AC - Les personnes en situation de crise',
      html: '<div class="grid g2"><div class="card"><h3>Silencieuses (hypoactives)</h3><ul><li><b>Sidération</b> : stupeur, paralysie physique et psychique, regard vide ; peut rester immobile dans le danger (une minute à plusieurs heures).</li><li><b>Actions automatiques</b> : gestes répétitifs, inutiles ; souvenir flou ensuite.</li><li>État dissociatif : coupée de ses émotions, parfois confuse, désorientée, amnésique.</li></ul><p class="small">Signe de détresse psychologique aiguë : orienter vers une prise en charge spécialisée (urgences, CUMP).</p></div><div class="card"><h3>Bruyantes (hyperactives)</h3><ul><li><b>Fuite panique</b> : impulsive, éperdue, bousculant autrui ; très contagieuse (panique collective).</li><li><b>Agitation désordonnée</b> : excitation, logorrhée, actions irréfléchies ; danger pour elle-même et pour les autres.</li></ul></div></div><ul class="check"><li>La victime peut passer d’une réaction à l’autre.</li><li>Une réaction qui semble adaptée ne garantit pas l’absence de blessure psychique.</li><li>Évolution possible vers un trouble de l’adaptation, un trouble de stress aigu (TSA) ou post-traumatique (TSPT).</li><li>Autres réactions : <b>choc de compassion</b> (tristesse, colère, impuissance), réaction à une perte.</li></ul>' }
  ],
  key: ['Crise = manifestation brusque, intense, de durée limitée.', 'Toujours penser à une cause physique (hypoglycémie, hypoxie, AVC, trauma crânien, intoxication).', 'Réactions silencieuses (sidération, automatismes) aussi graves que bruyantes (fuite panique, agitation).', 'Sécurité de l’équipe : retrait conservatoire possible.', 'CUMP en cas de nombreuses victimes.'],
  traps: ['Étiqueter « psychiatrique » sans avoir cherché une détresse vitale ou une hypoglycémie.', 'Croire qu’une victime calme et sidérée va bien.'],
  quiz: [
    { q: 'Un état de crise peut être l’expression :', c: ['D’un problème physique comme une hypoglycémie ou un AVC', 'Uniquement d’une maladie psychiatrique', 'Uniquement d’une intoxication alcoolique', 'D’une simulation dans la majorité des cas'], e: 'L’AC rappelle que la crise prend souvent l’allure d’un trouble psychiatrique alors qu’elle peut être physique.', s: 'definition' },
    { q: 'La sidération est une réaction :', c: ['Silencieuse (hypoactive)', 'Bruyante (hyperactive)', 'Normale sans risque', 'Uniquement observée chez l’enfant'], e: 'Stupeur, paralysie de la capacité d’agir : réaction silencieuse, signe de détresse aiguë.', s: 'reactions' },
    { q: 'Quelle réaction est particulièrement contagieuse ?', c: ['La fuite panique', 'La sidération', 'Le choc de compassion', 'L’amnésie'], e: 'La fuite panique peut dégénérer par imitation en panique collective.', s: 'reactions' },
    { q: 'Face à un risque de violence, le secouriste peut :', c: ['Se retirer par mesure conservatoire', 'Contenir physiquement seul la victime', 'Quitter l’intervention sans prévenir', 'Ignorer le risque'], e: 'L’AC cite la possibilité d’être contraint de se retirer par mesure conservatoire.', s: 'risques' }
  ]
});

VSAV.chap({
  id: 'brancardage-principes', part: 'foad', seq: 'FOAD 1.6 — Généralités sur le brancardage', title: 'Principes généraux du relevage et du brancardage', short: 'Principes du brancardage',
  motif: 'stretcher', accent: '#15803d', sources: ['AC - Principes généraux du brancardage (MAJ 02/2023)'],
  summary: 'Règles de manutention, règles de brancardage et matériels de relevage.',
  why: '<b>Pourquoi des règles strictes ?</b> Relever et brancarder comporte des risques pour la victime (chute, aggravation) <b>et pour le secouriste</b> (lésions dorso-lombaires). Les principes de stabilité, de prises fermes, de répartition des charges et de synchronisation sous les ordres d’un chef évitent ces risques ; un bon entraînement les rend automatiques.',
  sections: [
    { id: 'manutention', t: 'Les 4 principes de manutention', ic: 'hand', src: 'AC - Principes généraux du brancardage',
      html: '<ol><li><b>Stabilité des positions et sécurité des mouvements</b> : debout, pieds écartés et décalés ; à genoux en « trépied » ; dos plat, travail avec les membres inférieurs. Mieux vaut s’accroupir que se pencher.</li><li><b>Fermeté des prises</b> : à pleines mains, la charge porte sur les avant-bras.</li><li><b>Bonne répartition des charges</b> : 3 à 6 secouristes selon les cas, charge rapprochée des porteurs.</li><li><b>Synchronisation des mouvements</b> : doux et coordonnés, sous les ordres d’un chef.</li></ol>' },
    { id: 'regles', t: 'Règles du brancardage', ic: 'stretcher', src: 'AC - Principes généraux du brancardage',
      html: '<ul class="check"><li>Avant : arrimer ou sangler la victime ; placer les secouristes selon leur taille et leur force.</li><li>Pendant : brancard horizontal ; mouvements coordonnés, en marchant, sans secousse ni balancement ; <b>tête de la victime vers l’avant</b> en règle générale.</li><li>Le <b>chef se place de préférence à l’arrière</b> : il voit son équipe et surveille la victime.</li><li>Commandement en deux temps : ordre préparatoire puis ordre d’exécution (« Attention pour lever… Levez ! »), à voix haute et intelligible.</li></ul>',
      figs: [{ anim: 'brancard', cap: 'Animation : place des porteurs', txt: '<p>Change le nombre de porteurs et le terrain pour voir où se placent les secouristes.</p>', src: 'FT Brancardage à 3 / à 4 secouristes' }] },
    { id: 'materiel', t: 'Les matériels', ic: 'list', src: 'AC - Principes généraux du brancardage',
      html: '<div class="tw"><table><tr><th>Matériel</th><th>Caractéristiques</th></tr><tr><td>Brancard pliant à compas</td><td>Plat, fond en toile, hampes munies de pieds fixes, pliable dans la largeur ; bretelles possibles pour le brancardage à 3.</td></tr><tr><td>Brancard principal</td><td>Roues, seul ou sur chariot ; dossier (position demi-assise), repose-pied possible ; zone thoracique rigide pour la RCP.</td></tr><tr><td>Brancard de catastrophe</td><td>Plat, rigide, empilable.</td></tr><tr><td>Brancard cuillère</td><td>Deux parties glissées latéralement puis réunies ; cadre large de 43 cm au tronc, réglable en longueur ; 3 sangles ; blocs de tête possibles. Surtout pour relever et transférer.</td></tr><tr><td>Alèse portoir</td><td>Toile épaisse plastifiée, radiotransparente, 6 ou 8 poignées ; dispositif de transfert ; <b>ne constitue pas un plan dur</b>.</td></tr><tr><td>Barquette</td><td>Rigide, bords sur 4 côtés, sangles, 4 anneaux pour treuillage / hélitreuillage.</td></tr></table></div>' }
  ],
  key: ['Dos plat, travail avec les cuisses ; s’accroupir plutôt que se pencher.', 'Prises à pleines mains, charge sur les avant-bras.', '3 à 6 secouristes, charge rapprochée.', 'Ordres en deux temps donnés par un chef.', 'Tête de la victime vers l’avant, chef à l’arrière.', 'L’alèse portoir n’est pas un plan dur.'],
  traps: ['Porter du bout des doigts : la charge doit reposer sur les avant-bras.', 'Donner un ordre d’exécution sans ordre préparatoire.'],
  quiz: [
    { q: 'Où se place de préférence le chef lors d’un brancardage ?', c: ['À l’arrière', 'À l’avant, côté tête', 'Sur le côté', 'Il ne porte jamais'], e: 'À l’arrière : vision sur toute l’équipe et surveillance de la victime.', s: 'regles' },
    { q: 'En règle générale, la victime est brancardée :', c: ['Tête vers l’avant', 'Pieds vers l’avant', 'Assise', 'Sur le côté'], e: 'AC : placer la tête de la victime vers l’avant, en règle générale.', s: 'regles' },
    { q: 'Le commandement se fait :', c: ['En deux temps : ordre préparatoire puis ordre d’exécution', 'Par gestes uniquement', 'En un seul mot', 'Par chaque porteur à tour de rôle'], e: 'Exemple : « Attention pour lever… Levez ! ».', s: 'regles' },
    { q: 'Quelle affirmation sur l’alèse portoir est exacte ?', c: ['Elle ne constitue pas un plan dur rigide', 'Elle sert à immobiliser un traumatisé du rachis', 'Elle remplace le MID', 'Elle n’a pas de poignées'], e: 'Elle est principalement un dispositif de transfert et ne constitue pas un plan dur.', s: 'materiel' }
  ]
});

VSAV.chap({
  id: 'securite', part: 'foad', seq: 'FOAD 1.7 — Sécurité sur interventions particulières', title: 'Protection et sécurité sur interventions particulières', short: 'Sécurité sur intervention',
  motif: 'alert', accent: '#b45309', sources: ['AC - Protection et sécurité (MAJ 05/2024)'],
  summary: 'Accident électrique, accident de la route, monoxyde de carbone, incendie, substances dangereuses.',
  why: '<b>Pourquoi des règles par type de risque ?</b> Chaque danger a son piège : l’électricité se transmet par l’eau ou le métal, le CO est invisible, la fumée tue avant les flammes, un produit toxique agit à distance avec le vent. Connaître la parade de chaque risque permet de protéger les intervenants, la victime et les témoins — et d’éviter le <b>suraccident</b>.',
  sections: [
    { id: 'electrique', t: 'Accident électrique', ic: 'bolt', src: 'AC - Protection et sécurité',
      html: '<ul class="check"><li>Vérifier que la victime n’est pas en contact direct ou indirect (eau, surface métallique…) avec un appareil ou un câble.</li><li>Si c’est le cas : écarter les personnes et leur interdire de toucher la victime.</li><li>Couper le courant (disjoncteur) ou débrancher l’appareil ; <b>ne pas s’approcher avant d’être certain que l’alimentation est coupée</b>.</li><li>Câble basse ou haute tension au sol : ne pas s’approcher, attendre les équipes spécialisées.</li></ul>' },
    { id: 'route', t: 'Accident de la route', ic: 'car', src: 'AC - Protection et sécurité',
      steps: ['Mettre en œuvre les moyens de protection collective (gyrophares…).', 'Allumer les feux de détresse en approchant et ralentir.', 'Se garer si possible après le lieu de l’accident, sur le bas-côté ou la bande d’arrêt d’urgence.', 'Mettre un gilet haute visibilité avant de quitter le véhicule.', 'Baliser de part et d’autre à 150 à 200 m (triangle, sauf voies rapides / autoroutes, lampe, linge blanc, feux de détresse).', 'Interdire toute approche si un danger persiste (fuite de matières dangereuses, danger électrique…).', 'Ne pas fumer et ne pas laisser fumer ; feu naissant moteur : extincteur ou terre.', 'Couper le contact de chaque véhicule (clé / carte à distance : l’éloigner à plus de 5 m).', 'Serrer le frein à main ou caler le véhicule.'], stepsTitle: 'Protection d’un accident de la route' },
    { id: 'co', t: 'Monoxyde de carbone (CO)', ic: 'skull', src: 'AC - Protection et sécurité · Mémento SSUAP (RAD-57)',
      html: '<ul class="check"><li>Faire évacuer et rassembler les personnes ; aérer largement (s’engager en retenant sa respiration).</li><li>Alerter les sapeurs-pompiers (détecteurs).</li><li>Identifier l’appareil producteur (brasero, moteur thermique, échappement en milieu clos, cheminée, chauffe-eau…) et l’arrêter.</li></ul><div class="tw"><table><tr><th>HbCO (%)</th><th>Signes</th><th>Conduite (RAD-57)</th></tr><tr><td>0–4</td><td>Aucun (fumeur : +3 à 5 %)</td><td>Aucune</td></tr><tr><td>5–9</td><td>Maux de tête modérés</td><td>Aucune (normal pour un fumeur)</td></tr><tr><td>10–19</td><td>Maux de tête, essoufflement</td><td>Vérifier ventilation et circulation, O₂ 100 %, envisager transport</td></tr><tr><td>20–29</td><td>Nausées, fatigue, désorientation</td><td>O₂ 100 %, transport, envisager caisson</td></tr><tr><td>30–39</td><td>Maux de tête sévères, vomissements, vertiges, perte de connaissance</td><td>O₂ 100 %, transport, caisson hyperbare</td></tr><tr><td>40 et plus</td><td>Confusion, syncope, tachycardie → convulsions, choc, apnée → arythmies, coma, mort</td><td>O₂ 100 %, transport, caisson hyperbare</td></tr></table></div>' },
    { id: 'incendie', t: 'Incendie', ic: 'flame', src: 'AC - Protection et sécurité',
      html: '<ul class="check"><li>Alerter, faire évacuer (alarme ou alerte à la voix, guider vers les issues), fermer les portes derrière soi.</li><li>Jamais d’ascenseur ; ne pas s’engager dans un local ou escalier enfumé ; ne pas entrer dans un local en feu ; faire confiner les personnes non exposées (se manifester aux fenêtres).</li><li>Se protéger : vêtements mouillés sur le visage et les mains, se baisser près du sol.</li><li>Victime visible depuis l’entrée d’un local enfumé : dégagement d’urgence <b>en retenant sa respiration uniquement</b>, si capacités et configuration le permettent ; sinon informer les sapeurs-pompiers.</li><li>Fuite de gaz : ne pas entrer, rester à distance, empêcher l’accès, <b>aucune étincelle</b> (interrupteur, sonnette, lampe, téléphone).</li><li>Vêtements en feu : allonger la victime ; extincteur approprié en milieu professionnel, sinon étouffer avec une couverture ou un manteau retiré dès les flammes éteintes.</li></ul>' },
    { id: 'substances', t: 'Substances dangereuses', ic: 'skull', src: 'AC - Protection et sécurité',
      html: '<ul class="check"><li>Rester à distance de la fuite ; écarter les témoins ; interdire de fumer.</li><li><b>Rester en amont par rapport au vent</b> (émanations agissant à distance).</li><li>Alerter et signaler un éventuel panneau de danger sur le véhicule.</li></ul>' }
  ],
  key: ['Électricité : ne pas toucher avant coupure certaine ; câble au sol → attendre les spécialistes.', 'Route : gilet avant de sortir, balisage 150–200 m, contact coupé, carte éloignée à plus de 5 m, véhicule calé.', 'CO : évacuer, aérer, arrêter l’appareil ; O₂ 100 % dès 10 % d’HbCO (RAD-57).', 'Incendie : jamais d’ascenseur, portes fermées, se baisser.', 'Gaz : aucune étincelle. Toxiques : rester en amont du vent.'],
  traps: ['Approcher une victime au contact d’un câble tombé au sol.', 'Utiliser son téléphone ou un interrupteur dans un local où l’on suspecte une fuite de gaz.', 'Se placer sous le vent d’une fuite de produit toxique.'],
  quiz: [
    { q: 'À quelle distance baliser un accident de la route ?', c: ['150 à 200 m de part et d’autre', '20 à 50 m en amont seulement', '500 m', 'Pas de balisage nécessaire'], e: 'AC - Protection et sécurité : 150 à 200 m de part et d’autre.', s: 'route' },
    { q: 'Véhicule à carte de démarrage à distance : que faire de la carte ?', c: ['L’éloigner à plus de 5 m du véhicule', 'La laisser dans le véhicule', 'La donner à la victime', 'La casser'], e: 'Éloigner la carte à plus de 5 mètres.', s: 'route' },
    { q: 'Câble électrique haute tension au sol près de la victime :', c: ['Ne pas s’approcher et attendre les équipes spécialisées', 'Écarter le câble avec un bâton en bois', 'Tirer la victime par les vêtements', 'Couper le câble'], e: 'En présence d’un câble basse ou haute tension au sol : ne pas s’approcher.', s: 'electrique' },
    { q: 'Fuite de gaz suspectée dans un local :', c: ['Ne pas entrer, rester à distance, éviter toute étincelle', 'Entrer pour ouvrir les fenêtres et allumer la lumière', 'Appeler depuis l’intérieur du local', 'Sonner pour prévenir les occupants'], e: 'Ne pas pénétrer, empêcher l’accès, ne pas provoquer d’étincelles.', s: 'incendie' },
    { q: 'Face à une fuite de substance toxique, où se placer ?', c: ['En amont par rapport au vent', 'Sous le vent pour sentir l’odeur', 'Au plus près pour identifier le produit', 'N’importe où'], e: 'Rester en amont de l’accident par rapport au vent.', s: 'substances' },
    { q: 'Selon le guide RAD-57, à partir de quel taux d’HbCO la conduite inclut O₂ 100 % ?', c: ['10–19 %', '0–4 %', '5–9 %', '60 % uniquement'], e: '10–19 % : vérifier ventilation et circulation, oxygène 100 %, envisager le transport.', s: 'co' }
  ]
});
